  ('e2000000-0000-4000-b000-00000000155e', 'e2000000-0000-4000-a000-000000000223', 0, 'A humanidade do rei, pois retrata um homem comum, sem os adornos próprios à vestimenta real.', false),
  ('e2000000-0000-4000-b000-00000000155f', 'e2000000-0000-4000-a000-000000000223', 1, 'A unidade entre o público e o privado, pois a figura do rei com a vestimenta real representa o público e sem a vestimenta real, o privado.', false),
  ('e2000000-0000-4000-b000-000000001560', 'e2000000-0000-4000-a000-000000000223', 2, 'O vínculo entre monarquia e povo, pois leva ao conhecimento do público a figura de um rei  despretensioso e distante do poder político.', false),
  ('e2000000-0000-4000-b000-000000001561', 'e2000000-0000-4000-a000-000000000223', 3, 'O gosto estético refinado do rei, pois evidencia a elegância dos trajes reais em relação aos de outros membros da corte.', false),
  ('e2000000-0000-4000-b000-000000001562', 'e2000000-0000-4000-a000-000000000223', 4, 'A importância da vestimenta para a constituição simbólica do rei, pois o corpo político adornado esconde os defeitos do corpo pessoal.', true),
  ('e2000000-0000-4000-b000-000000001568', 'e2000000-0000-4000-a000-000000000224', 0, 'A reivindicação de autonomia da capacidade racional como expressão da maioridade.', true),
