  ('e2000000-0000-4000-b000-00000000156b', 'e2000000-0000-4000-a000-000000000224', 3, 'A compreensão de verdades religiosas que libertam o homem da falta de entendimento.', false),
  ('e2000000-0000-4000-b000-00000000156c', 'e2000000-0000-4000-a000-000000000224', 4, 'A emancipação da subjetividade humana de ideologias produzidas pela própria razão.', false),
  ('e2000000-0000-4000-b000-000000001572', 'e2000000-0000-4000-a000-000000000225', 0, 'Incompatibilidade entre os modos democráticos de convívio social e a presença de aparatos de controle policial.', false),
  ('e2000000-0000-4000-b000-000000001573', 'e2000000-0000-4000-a000-000000000225', 1, 'Manutenção de práticas repressivas herdadas dos períodos ditatoriais sob a forma de leis e atos administrativos.', false),
  ('e2000000-0000-4000-b000-000000001574', 'e2000000-0000-4000-a000-000000000225', 2, 'Inabilidade das forças militares em conter a violência decorrente das ondas migratórias nas grandes cidades brasileiras.', false),
  ('e2000000-0000-4000-b000-000000001575', 'e2000000-0000-4000-a000-000000000225', 3, 'Dificuldade histórica da sociedade brasileira em institucionalizar formas de controle social compatíveis com valores democráticos.', true),
  ('e2000000-0000-4000-b000-000000001576', 'e2000000-0000-4000-a000-000000000225', 4, 'Incapacidade das instituições político-legislativas em formular mecanismos de controle social específicos à realidade social brasileira.', false),
