  ('e2000000-0000-4000-b000-00000000159a', 'e2000000-0000-4000-a000-000000000229', 0, 'Ao status de cidadania que o indivíduo adquire ao tomar as decisões por si mesmo.', false),
  ('e2000000-0000-4000-b000-00000000159b', 'e2000000-0000-4000-a000-000000000229', 1, 'Ao condicionamento da liberdade dos cidadãos à conformidade às leis.', true),
  ('e2000000-0000-4000-b000-00000000159c', 'e2000000-0000-4000-a000-000000000229', 2, 'À possibilidade de o cidadão participar no poder e, nesse caso, livre da submissão às leis.', false),
  ('e2000000-0000-4000-b000-00000000159d', 'e2000000-0000-4000-a000-000000000229', 3, 'Ao livre-arbítrio do cidadão em relação àquilo que é proibido, desde que ciente das consequências.', false),
  ('e2000000-0000-4000-b000-00000000159e', 'e2000000-0000-4000-a000-000000000229', 4, 'Ao direito do cidadão exercer sua vontade de acordo com seus valores pessoais.', false),
  ('e2000000-0000-4000-b000-0000000015a4', 'e2000000-0000-4000-a000-00000000022a', 0, 'A ineficiência do sistema judiciário inglês no território indiano.', false),
