  ('e2000000-0000-4000-b000-0000000015a8', 'e2000000-0000-4000-a000-00000000022a', 4, 'A indiferença das autoridades britânicas frente ao apelo popular hindu.', false),
  ('e2000000-0000-4000-b000-0000000015ae', 'e2000000-0000-4000-a000-00000000022b', 0, 'A secessão, pela qual a minoria discriminada obteria a igualdade de direitos na condição da sua concentração espacial, num tipo de independência nacional.', false),
  ('e2000000-0000-4000-b000-0000000015af', 'e2000000-0000-4000-a000-00000000022b', 1, 'A reunificação da sociedade que se encontra fragmentada em grupos de diferentes comunidades étnicas, confissões religiosas e formas de vida, em torno da coesão de uma cultura política nacional.', false),
  ('e2000000-0000-4000-b000-0000000015b0', 'e2000000-0000-4000-a000-00000000022b', 2, 'A coexistência das diferenças, considerando a possibilidade de os discursos de autoentendimento se submeterem ao debate público, cientes de que estarão vinculados à coerção do melhor argumento.', true),
  ('e2000000-0000-4000-b000-0000000015b1', 'e2000000-0000-4000-a000-00000000022b', 3, 'A autonomia dos indivíduos que, ao chegarem à vida adulta, tenham condições de se libertar das tradições de suas origens em nome da harmonia da política nacional.', false),
  ('e2000000-0000-4000-b000-0000000015b2', 'e2000000-0000-4000-a000-00000000022b', 4, 'O desaparecimento de quaisquer limitações, tais como linguagem política ou distintas convenções de comportamento, para compor a arena política a ser compartilhada.', false),
  ('e2000000-0000-4000-b000-0000000015b8', 'e2000000-0000-4000-a000-00000000022c', 0, 'Expulsão dos indígenas para fortalecer o clero católico.', false),
