  ('e2000000-0000-4000-b000-0000000015bc', 'e2000000-0000-4000-a000-00000000022c', 4, 'Fundação de cidades para controlar a circulação de riquezas.', true),
  ('e2000000-0000-4000-b000-0000000015c2', 'e2000000-0000-4000-a000-00000000022d', 0, 'Redução da influência do papa – Teocracia.', false),
  ('e2000000-0000-4000-b000-0000000015c3', 'e2000000-0000-4000-a000-00000000022d', 1, 'Limitação do poder do soberano – Absolutismo.', true),
  ('e2000000-0000-4000-b000-0000000015c4', 'e2000000-0000-4000-a000-00000000022d', 2, 'Ampliação da dominação da nobreza – República.', false),
  ('e2000000-0000-4000-b000-0000000015c5', 'e2000000-0000-4000-a000-00000000022d', 3, 'Expansão da força do presidente – Parlamentarismo.', false),
  ('e2000000-0000-4000-b000-0000000015c6', 'e2000000-0000-4000-a000-00000000022d', 4, 'Restrição da competência do congresso – Presidencialismo.', false),
  ('e2000000-0000-4000-b000-0000000015cc', 'e2000000-0000-4000-a000-00000000022e', 0, 'À experiência francesa, expressa no chamado à luta contra a ditadura.', false),
  ('e2000000-0000-4000-b000-0000000015cd', 'e2000000-0000-4000-a000-00000000022e', 1, 'Aos ideais republicanos, indicados no destaque à bandeira paulista.', false),
  ('e2000000-0000-4000-b000-0000000015ce', 'e2000000-0000-4000-a000-00000000022e', 2, 'Ao protagonismo das Forças Armadas, representadas pelo militar que empunha a bandeira.', false),
  ('e2000000-0000-4000-b000-0000000015cf', 'e2000000-0000-4000-a000-00000000022e', 3, 'Ao bandeirantismo, símbolo paulista apresentado em primeiro plano.', true),
  ('e2000000-0000-4000-b000-0000000015d0', 'e2000000-0000-4000-a000-00000000022e', 4, 'Ao papel figurativo de Vargas na política, enfatizado pela pequenez de sua figura no cartaz.', false),
  ('e2000000-0000-4000-b000-0000000015d6', 'e2000000-0000-4000-a000-00000000022f', 0, 'Submeter a memória e o patrimônio nacional ao controle dos órgãos públicos, de acordo com a tendência autoritária do Estado Novo.', false),
  ('e2000000-0000-4000-b000-0000000015d7', 'e2000000-0000-4000-a000-00000000022f', 1, 'Transferir para a iniciativa privada a responsabilidade de preservação do patrimônio nacional, por meio de leis de incentivo fiscal.', false),
