  ('e2000000-0000-4000-b000-000000001810', 'e2000000-0000-4000-a000-000000000268', 0, 'Promove uma reação de substituição no hidrocarboneto, tornando-o menos letal ao ambiente.', false),
  ('e2000000-0000-4000-b000-000000001811', 'e2000000-0000-4000-a000-000000000268', 1, 'A hidrólise do para-dodecil-benzenossulfonato de sódio produz energia térmica suficiente para vaporizar o hidrocarboneto.', false),
  ('e2000000-0000-4000-b000-000000001812', 'e2000000-0000-4000-a000-000000000268', 2, 'A mistura desses reagentes provoca a combustão do hidrocarboneto, o que diminui a quantidade dessa substância na natureza.', false),
  ('e2000000-0000-4000-b000-000000001813', 'e2000000-0000-4000-a000-000000000268', 3, 'A solução de para-dodecil-benzenossulfonato possibilita a solubilização do hidrocarboneto.', true),
  ('e2000000-0000-4000-b000-000000001814', 'e2000000-0000-4000-a000-000000000268', 4, 'O reagente adicionado provoca uma solidificação do hidrocarboneto, o que facilita sua retirada do ambiente.', false),
  ('e2000000-0000-4000-b000-00000000181a', 'e2000000-0000-4000-a000-000000000269', 0, 'Dos biocombustíveis, pois tem menor impacto ambiental e maior disponibilidade.', false),
  ('e2000000-0000-4000-b000-00000000181b', 'e2000000-0000-4000-a000-000000000269', 1, 'Solar, pelo seu baixo custo e pelas características do país favoráveis à sua implantação.', false),
  ('e2000000-0000-4000-b000-00000000181c', 'e2000000-0000-4000-a000-000000000269', 2, 'Nuclear, por ter menor risco ambiental e ser adequada a locais com menor extensão territorial.', false),
  ('e2000000-0000-4000-b000-00000000181d', 'e2000000-0000-4000-a000-000000000269', 3, 'Hidráulica, devido ao relevo, à extensão territorial do país e aos recursos naturais disponíveis.', false),
  ('e2000000-0000-4000-b000-00000000181e', 'e2000000-0000-4000-a000-000000000269', 4, 'Eólica, pelas características do país e por não gerar gases do efeito estufa nem resíduos de operação.', true),
