  ('e2000000-0000-4000-b000-000000001838', 'e2000000-0000-4000-a000-00000000026c', 0, 'A maior velocidade orbital da Terra faz com que, em certas épocas, ela ultrapasse Marte.', true),
  ('e2000000-0000-4000-b000-000000001839', 'e2000000-0000-4000-a000-00000000026c', 1, 'A presença de outras estrelas faz com que sua trajetória seja desviada por meio da atração gravitacional.', false),
  ('e2000000-0000-4000-b000-00000000183a', 'e2000000-0000-4000-a000-00000000026c', 2, 'A órbita de Marte, em torno do Sol, possui uma forma elíptica mais acentuada que a dos demais planetas.', false),
  ('e2000000-0000-4000-b000-00000000183b', 'e2000000-0000-4000-a000-00000000026c', 3, 'A atração gravitacional entre a Terra e Marte faz com que este planeta apresente uma órbita irregular em torno do Sol.', false),
  ('e2000000-0000-4000-b000-00000000183c', 'e2000000-0000-4000-a000-00000000026c', 4, 'A proximidade de Marte com Júpiter, em algumas épocas do ano, faz com que a atração gravitacional de Júpiter interfira em seu movimento.', false),
