  ('e2000000-0000-4000-b000-00000000187e', 'e2000000-0000-4000-a000-000000000273', 0, 'Desestabilizaram o relógio biológico dos animais, causando alterações no código genético.', false),
  ('e2000000-0000-4000-b000-00000000187f', 'e2000000-0000-4000-a000-000000000273', 1, 'Reduziram a penetração da luz solar até a superfície da Terra, interferindo no fluxo energético das teias tróficas.', true),
  ('e2000000-0000-4000-b000-000000001880', 'e2000000-0000-4000-a000-000000000273', 2, 'Causaram uma série de intoxicações nos animais, provocando a bioacumulação de partículas de poeira nos organismos.', false),
  ('e2000000-0000-4000-b000-000000001881', 'e2000000-0000-4000-a000-000000000273', 3, 'Resultaram na sedimentação das partículas de poeira levantada com o impacto do meteoro, provocando o desaparecimento de rios e lagos.', false),
  ('e2000000-0000-4000-b000-000000001882', 'e2000000-0000-4000-a000-000000000273', 4, 'Evitaram a precipitação de água até a superfície da Terra, causando uma grande seca que impediu a retroalimentação do ciclo hidrológico.', false),
  ('e2000000-0000-4000-b000-000000001888', 'e2000000-0000-4000-a000-000000000274', 0, 'Somente o lítio, pois ele possui o menor potencial de redução.', false),
  ('e2000000-0000-4000-b000-000000001889', 'e2000000-0000-4000-a000-000000000274', 1, 'Somente o cobre, pois ele possui o maior potencial de redução.', false),
  ('e2000000-0000-4000-b000-00000000188a', 'e2000000-0000-4000-a000-000000000274', 2, 'Somente o potássio, pois ele possui potencial de redução mais próximo do magnésio.', false),
  ('e2000000-0000-4000-b000-00000000188b', 'e2000000-0000-4000-a000-000000000274', 3, 'Somente o cobre e o zinco, pois eles sofrem oxidação mais facilmente que o alumínio.', false),
  ('e2000000-0000-4000-b000-00000000188c', 'e2000000-0000-4000-a000-000000000274', 4, 'Somente o lítio e o potássio, pois seus potenciais de redução são menores do que o do alumínio.', true),
  ('e2000000-0000-4000-b000-000000001892', 'e2000000-0000-4000-a000-000000000275', 0, 'O tipo de combustível, fóssil, que utilizam. Sendo um insumo não renovável, em algum momento estará esgotado.', false),
  ('e2000000-0000-4000-b000-000000001893', 'e2000000-0000-4000-a000-000000000275', 1, 'Um dos princípios da termodinâmica, segundo o qual o rendimento de uma máquina térmica nunca atinge o ideal.', true),
  ('e2000000-0000-4000-b000-000000001894', 'e2000000-0000-4000-a000-000000000275', 2, 'O funcionamento cíclico de todos os motores. A repetição contínua dos movimentos exige que parte da energia seja transferida ao próximo ciclo.', false),
  ('e2000000-0000-4000-b000-000000001895', 'e2000000-0000-4000-a000-000000000275', 3, 'As forças de atrito inevitável entre as peças. Tais forças provocam desgastes contínuos que com o tempo levam qualquer material à fadiga e ruptura.', false),
  ('e2000000-0000-4000-b000-000000001896', 'e2000000-0000-4000-a000-000000000275', 4, 'A temperatura em que eles trabalham. Para atingir o plasma, é necessária uma temperatura maior que a de fusão do aço com que se fazem os motores.', false),
  ('e2000000-0000-4000-b000-00000000189c', 'e2000000-0000-4000-a000-000000000276', 0, 'O material é incapaz de acumular radiação, não se tornando radioativo por ter sido irradiado.', true),
  ('e2000000-0000-4000-b000-00000000189d', 'e2000000-0000-4000-a000-000000000276', 1, 'A utilização de uma embalagem é suficiente para bloquear a radiação emitida pelo material.', false),
  ('e2000000-0000-4000-b000-00000000189e', 'e2000000-0000-4000-a000-000000000276', 2, 'A contaminação radioativa do material não se prolifera da mesma forma que as infecções por microrganismos.', false),
  ('e2000000-0000-4000-b000-00000000189f', 'e2000000-0000-4000-a000-000000000276', 3, 'O material irradiado emite radiação de intensidade abaixo daquela que ofereceria risco à saúde.', false),
  ('e2000000-0000-4000-b000-0000000018a0', 'e2000000-0000-4000-a000-000000000276', 4, 'O intervalo de tempo após a esterilização é suficiente para que o material não emita mais radiação.', false),
  ('e2000000-0000-4000-b000-0000000018a6', 'e2000000-0000-4000-a000-000000000277', 0, 'As sementes aladas, que favorecem a dispersão aérea.', false),
  ('e2000000-0000-4000-b000-0000000018a7', 'e2000000-0000-4000-a000-000000000277', 1, 'Os arquegônios, que protegem o embrião multicelular.', false),
  ('e2000000-0000-4000-b000-0000000018a8', 'e2000000-0000-4000-a000-000000000277', 2, 'Os grãos de pólen, que garantem a polinização cruzada.', true),
  ('e2000000-0000-4000-b000-0000000018a9', 'e2000000-0000-4000-a000-000000000277', 3, 'Os frutos, que promovem uma maior eficiência reprodutiva.', false),
  ('e2000000-0000-4000-b000-0000000018aa', 'e2000000-0000-4000-a000-000000000277', 4, 'Os vasos condutores, que possibilitam o transporte da seiva bruta.', false),
  ('e2000000-0000-4000-b000-0000000018b0', 'e2000000-0000-4000-a000-000000000278', 0, 'Adsorção de íons Na+ sobre a superfície da célula.', false),
  ('e2000000-0000-4000-b000-0000000018b1', 'e2000000-0000-4000-a000-000000000278', 1, 'Difusão rápida de íons Na+ para o interior da célula.', false),
  ('e2000000-0000-4000-b000-0000000018b2', 'e2000000-0000-4000-a000-000000000278', 2, 'Diminuição da concentração das soluções presentes na célula.', false),
  ('e2000000-0000-4000-b000-0000000018b3', 'e2000000-0000-4000-a000-000000000278', 3, 'Transferência de íons Na+ da célula para a solução.', false),
  ('e2000000-0000-4000-b000-0000000018b4', 'e2000000-0000-4000-a000-000000000278', 4, 'Transferência de moléculas de água do interior da célula para a solução.', true),
  ('e2000000-0000-4000-b000-0000000018ba', 'e2000000-0000-4000-a000-000000000279', 0, 'O consumo de carnes de animais silvestres que são hospedeiros do vetor da doença.', false),
  ('e2000000-0000-4000-b000-0000000018bb', 'e2000000-0000-4000-a000-000000000279', 1, 'A utilização de adubos químicos na agricultura que aceleram o ciclo reprodutivo do barbeiro.', false),
  ('e2000000-0000-4000-b000-0000000018bc', 'e2000000-0000-4000-a000-000000000279', 2, 'A ausência de saneamento básico que favorece a proliferação do protozoário em regiões habitadas por humanos.', false),
  ('e2000000-0000-4000-b000-0000000018bd', 'e2000000-0000-4000-a000-000000000279', 3, 'A poluição dos rios e lagos com pesticidas que exterminam o predador das larvas do inseto transmissor da doença.', false),
  ('e2000000-0000-4000-b000-0000000018be', 'e2000000-0000-4000-a000-000000000279', 4, 'O desmatamento que provoca a migração ou o desaparecimento dos animais silvestres dos quais o barbeiro se alimenta.', true),
