  ('e2000000-0000-4000-b000-0000000018d0', 'e2000000-0000-4000-a000-00000000027b', 2, 'Anfotérica, ou seja, podem comportar-se como ácidos e bases.', false),
  ('e2000000-0000-4000-b000-0000000018d1', 'e2000000-0000-4000-a000-00000000027b', 3, 'Insaturada, ou seja, possuírem duplas ligações em sua estrutura.', false),
