  ('e2000000-0000-4000-b000-00000000203a', 'e2000000-0000-4000-a000-000000000339', 0, 'Intérprete do conquistador, possibilitando-lhe conhecer as fragilidades do Império.', true),
  ('e2000000-0000-4000-b000-00000000203b', 'e2000000-0000-4000-a000-000000000339', 1, 'Escrava dos espanhóis, colocando-se a serviço dos objetivos da Coroa.', false),
  ('e2000000-0000-4000-b000-00000000203c', 'e2000000-0000-4000-a000-000000000339', 2, 'Amante do conquistador, dando origem à miscigenação étnica.', false),
