  ('e2000000-0000-4000-b000-000000002045', 'e2000000-0000-4000-a000-00000000033a', 1, 'Descrever suas criações na área da tecnologia.', false),
  ('e2000000-0000-4000-b000-000000002046', 'e2000000-0000-4000-a000-00000000033a', 2, 'Enaltecer sua contribuição para o mundo digital.', true),
  ('e2000000-0000-4000-b000-000000002047', 'e2000000-0000-4000-a000-00000000033a', 3, 'Lamentar sua ausência na criação de novas tecnologias.', false),
  ('e2000000-0000-4000-b000-000000002048', 'e2000000-0000-4000-a000-00000000033a', 4, 'Discutir o impacto de seu trabalho para a geração digital.', false),
  ('e2000000-0000-4000-b000-00000000204e', 'e2000000-0000-4000-a000-00000000033b', 0, 'Influenciável pela opinião das demais.', false),
  ('e2000000-0000-4000-b000-00000000204f', 'e2000000-0000-4000-a000-00000000033b', 1, 'Consciente de sua diferença perante as outras.', false),
  ('e2000000-0000-4000-b000-000000002050', 'e2000000-0000-4000-a000-00000000033b', 2, 'Conformada por não pertencer a nenhum grupo.', false),
  ('e2000000-0000-4000-b000-000000002051', 'e2000000-0000-4000-a000-00000000033b', 3, 'Corajosa diante de situações arriscadas.', false),
  ('e2000000-0000-4000-b000-000000002052', 'e2000000-0000-4000-a000-00000000033b', 4, 'Capaz de transformar mau humor em pranto.', true),
  ('e2000000-0000-4000-b000-000000002058', 'e2000000-0000-4000-a000-00000000033c', 0, '“Lá na minha escola, aprendi a jogar capoeira para uma apresentação no Dia da Consciência Negra.”', false),
  ('e2000000-0000-4000-b000-000000002059', 'e2000000-0000-4000-a000-00000000033c', 1, '“Outro dia assisti na TV uma reportagem sobre respeito à diversidade. Gente de todos os tipos, várias tribos. Curti bastante.”', false),
  ('e2000000-0000-4000-b000-00000000205a', 'e2000000-0000-4000-a000-00000000033c', 2, '“Eu me inscrevi no Programa Jovens Embaixadores para mostrar o que tem de bom em meu país e conhecer outras formas de ser.”', true),
  ('e2000000-0000-4000-b000-00000000205b', 'e2000000-0000-4000-a000-00000000033c', 3, '“Curto muito bater papo na internet. Meus amigos estrangeiros me ajudam a aperfeiçoar minha proficiência em língua estrangeira.”', false),
  ('e2000000-0000-4000-b000-00000000205c', 'e2000000-0000-4000-a000-00000000033c', 4, '“Pesquisei em sites de culinária e preparei uma festa árabe para uns amigos da escola. Eles adoraram, principalmente, os doces!”', false),
  ('e2000000-0000-4000-b000-000000002062', 'e2000000-0000-4000-a000-00000000033d', 0, 'As especificidades culturais rompem com a unidade hispânica.', false),
  ('e2000000-0000-4000-b000-000000002063', 'e2000000-0000-4000-a000-00000000033d', 1, 'As variedades do espanhol têm igual relevância linguística e cultural.', true),
  ('e2000000-0000-4000-b000-000000002064', 'e2000000-0000-4000-a000-00000000033d', 2, 'A unidade linguística do espanhol fortalece a identidade cultural hispânica.', false),
  ('e2000000-0000-4000-b000-000000002065', 'e2000000-0000-4000-a000-00000000033d', 3, 'A consolidação das diferenças da língua prejudica sua projeção mundial.', false),
  ('e2000000-0000-4000-b000-000000002066', 'e2000000-0000-4000-a000-00000000033d', 4, 'A unificação da língua enriquece a competência linguística dos falantes.', false),
  ('e2000000-0000-4000-b000-00000000206c', 'e2000000-0000-4000-a000-00000000033e', 0, 'Decide tirar a neve do quintal para convencer seu pai sobre seu discurso.', false),
  ('e2000000-0000-4000-b000-00000000206d', 'e2000000-0000-4000-a000-00000000033e', 1, 'Culpa o pai por exercer influência negativa na formação de sua personalidade.', false),
  ('e2000000-0000-4000-b000-00000000206e', 'e2000000-0000-4000-a000-00000000033e', 2, 'Comenta que suas discussões com o pai não correspondem às suas expectativas.', true),
  ('e2000000-0000-4000-b000-00000000206f', 'e2000000-0000-4000-a000-00000000033e', 3, 'Conclui que os acontecimentos ruins não fazem falta para a sociedade.', false),
