  ('e2000000-0000-4000-b000-0000000020bc', 'e2000000-0000-4000-a000-000000000346', 0, 'O discurso ambientalista propõe formas radicais de resolver os problemas climáticos.', false),
  ('e2000000-0000-4000-b000-0000000020bd', 'e2000000-0000-4000-a000-000000000346', 1, 'A preservação da vida na Terra depende de ações de dessalinização da água marinha.', false),
  ('e2000000-0000-4000-b000-0000000020be', 'e2000000-0000-4000-a000-000000000346', 2, 'A acomodação da topografia terrestre desencadeia o natural degelo das calotas polares.', false),
  ('e2000000-0000-4000-b000-0000000020bf', 'e2000000-0000-4000-a000-000000000346', 3, 'O descongelamento das calotas polares diminui a quantidade de água doce potável do mundo.', false),
  ('e2000000-0000-4000-b000-0000000020c0', 'e2000000-0000-4000-a000-000000000346', 4, 'A agressão ao planeta é dependente da posição assumida pelo homem frente aos problemas ambientais.', true),
  ('e2000000-0000-4000-b000-0000000020c6', 'e2000000-0000-4000-a000-000000000347', 0, 'Discussão da dificuldade de se fazer arte inovadora no mundo contemporâneo.', false),
