  ('e2000000-0000-4000-b000-0000000020c9', 'e2000000-0000-4000-a000-000000000347', 3, 'Tematização do fazer artístico, pela discussão do ato de construção da própria obra.', true),
  ('e2000000-0000-4000-b000-0000000020ca', 'e2000000-0000-4000-a000-000000000347', 4, 'Valorização do efeito de estranhamento causado no público, o que faz a obra ser reconhecida.', false),
