  ('e2000000-0000-4000-b000-0000000020d1', 'e2000000-0000-4000-a000-000000000348', 1, 'Palavras e construções que evitem ambiguidade.', true),
  ('e2000000-0000-4000-b000-0000000020d2', 'e2000000-0000-4000-a000-000000000348', 2, 'Expressões informais para apresentar os direitos.', false),
  ('e2000000-0000-4000-b000-0000000020d3', 'e2000000-0000-4000-a000-000000000348', 3, 'Frases na ordem direta para apresentar as informações mais relevantes.', false),
  ('e2000000-0000-4000-b000-0000000020d4', 'e2000000-0000-4000-a000-000000000348', 4, 'Exemplificações que auxiliem a compreensão dos conceitos formulados.', false),
  ('e2000000-0000-4000-b000-0000000020da', 'e2000000-0000-4000-a000-000000000349', 0, 'A internet atribui verdadeiros valores culturais aos seus usuários.', false),
  ('e2000000-0000-4000-b000-0000000020db', 'e2000000-0000-4000-a000-000000000349', 1, 'A consciência das sociedades foi estabelecida com o advento da internet.', false),
  ('e2000000-0000-4000-b000-0000000020dc', 'e2000000-0000-4000-a000-000000000349', 2, 'A revolução tecnológica tem como principal objetivo a deposição de governantes antidemocráticos.', false),
  ('e2000000-0000-4000-b000-0000000020dd', 'e2000000-0000-4000-a000-000000000349', 3, 'Os recursos tecnológicos estão a serviço dos opressores e do fortalecimento de suas práticas políticas.', false),
  ('e2000000-0000-4000-b000-0000000020de', 'e2000000-0000-4000-a000-000000000349', 4, 'Os sistemas de comunicação são mecanismos importantes, de adesão e compartilhamento de valores sociais.', true),
  ('e2000000-0000-4000-b000-0000000020e4', 'e2000000-0000-4000-a000-00000000034a', 0, 'Que sábia iniciativa! Os prédios em péssimo estado de conservação devem ser derrubados.', false),
  ('e2000000-0000-4000-b000-0000000020e5', 'e2000000-0000-4000-a000-00000000034a', 1, 'Até que enfim! Os edifícios localizados nesse trecho descaracterizam o conjunto arquitetônico da Rua Augusta.', false),
  ('e2000000-0000-4000-b000-0000000020e6', 'e2000000-0000-4000-a000-00000000034a', 2, 'Parabéns! O poder público precisa mostrar sua força como guardião das tradições dos moradores locais.', false),
  ('e2000000-0000-4000-b000-0000000020e7', 'e2000000-0000-4000-a000-00000000034a', 3, 'Justa decisão! O governo dá mais um passo rumo à eliminação do problema da falta de moradias populares.', false),
  ('e2000000-0000-4000-b000-0000000020e8', 'e2000000-0000-4000-a000-00000000034a', 4, 'Congratulações! O patrimônio histórico da cidade merece todo empenho para ser preservado.', true),
  ('e2000000-0000-4000-b000-0000000020ee', 'e2000000-0000-4000-a000-00000000034b', 0, 'A falta de atividade física somada a uma alimentação nutricionalmente desequilibrada constituem fatores relacionados ao aparecimento de doenças crônicas entre os adolescentes.', true),
  ('e2000000-0000-4000-b000-0000000020ef', 'e2000000-0000-4000-a000-00000000034b', 1, 'A diminuição do consumo de alimentos fontes de carboidratos combinada com um maior consumo de alimentos ricos em proteínas contribuíram para o aumento da obesidade entre os adolescentes.', false),
  ('e2000000-0000-4000-b000-0000000020f0', 'e2000000-0000-4000-a000-00000000034b', 2, 'A maior participação dos alimentos industrializados e gordurosos na dieta da população adolescente tem tornado escasso o consumo de sais e açúcares, o que prejudica o equilíbrio metabólico.', false),
  ('e2000000-0000-4000-b000-0000000020f1', 'e2000000-0000-4000-a000-00000000034b', 3, 'A ocorrência de casos de hipertensão e diabetes entre os adolescentes advém das condições de alimentação, enquanto que na população adulta os fatores hereditários são preponderantes.', false),
  ('e2000000-0000-4000-b000-0000000020f2', 'e2000000-0000-4000-a000-00000000034b', 4, 'A prática regular de atividade física é um importante fator de controle da diabetes entre a população adolescente, por provocar um constante aumento da pressão arterial sistólica.', false),
  ('e2000000-0000-4000-b000-0000000020f8', 'e2000000-0000-4000-a000-00000000034c', 0, 'Difundir a origem de marcantes diferenças sociais.', false),
  ('e2000000-0000-4000-b000-0000000020f9', 'e2000000-0000-4000-a000-00000000034c', 1, 'Estabelecer uma postura proativa da sociedade.', false),
  ('e2000000-0000-4000-b000-0000000020fa', 'e2000000-0000-4000-a000-00000000034c', 2, 'Provocar a reflexão sobre essa realidade.', true),
  ('e2000000-0000-4000-b000-0000000020fb', 'e2000000-0000-4000-a000-00000000034c', 3, 'Propor alternativas para solucionar esse problema.', false),
  ('e2000000-0000-4000-b000-0000000020fc', 'e2000000-0000-4000-a000-00000000034c', 4, 'Retratar como a questão é enfrentada em vários países do mundo.', false),
  ('e2000000-0000-4000-b000-000000002102', 'e2000000-0000-4000-a000-00000000034d', 0, 'A opressão das minorias sociais.', false),
  ('e2000000-0000-4000-b000-000000002103', 'e2000000-0000-4000-a000-00000000034d', 1, 'Carência de recursos tecnológicos.', false),
  ('e2000000-0000-4000-b000-000000002104', 'e2000000-0000-4000-a000-00000000034d', 2, 'Falta de liberdade de expressão.', false),
  ('e2000000-0000-4000-b000-000000002105', 'e2000000-0000-4000-a000-00000000034d', 3, 'Defesa da qualificação profissional.', false),
  ('e2000000-0000-4000-b000-000000002106', 'e2000000-0000-4000-a000-00000000034d', 4, 'Reação ao controle do pensamento coletivo.', true),
  ('e2000000-0000-4000-b000-00000000210c', 'e2000000-0000-4000-a000-00000000034e', 0, 'Possuir como característica principal os atributos divinos e religiosos e, por isso, identificar uma nação ou região.', false),
  ('e2000000-0000-4000-b000-00000000210d', 'e2000000-0000-4000-a000-00000000034e', 1, 'Abordar as tradições e costumes de determinados povos ou regiões distintas de uma mesma nação.', true),
  ('e2000000-0000-4000-b000-00000000210e', 'e2000000-0000-4000-a000-00000000034e', 2, 'Apresentar cunho artístico e técnicas apuradas, sendo, também, considerada dança-espetáculo.', false),
  ('e2000000-0000-4000-b000-00000000210f', 'e2000000-0000-4000-a000-00000000034e', 3, 'Necessitar de vestuário específico para a sua prática, o qual define seu país de origem.', false),
  ('e2000000-0000-4000-b000-000000002110', 'e2000000-0000-4000-a000-00000000034e', 4, 'Acontecer em salões e festas e ser influenciada por diversos gêneros musicais.', false),
  ('e2000000-0000-4000-b000-000000002116', 'e2000000-0000-4000-a000-00000000034f', 0, 'Enfatiza a metáfora de que o autor se vale para desenvolver seu ponto de vista sobre a arte de argumentar.', false),
  ('e2000000-0000-4000-b000-000000002117', 'e2000000-0000-4000-a000-00000000034f', 1, 'Diz respeito a um recurso de metalinguagem, evidenciando as relações e as estruturas presentes no enunciado.', false),
  ('e2000000-0000-4000-b000-000000002118', 'e2000000-0000-4000-a000-00000000034f', 2, 'É um recurso estilístico que promove satisfatoriamente a sequenciação de ideias, introduzindo apostos exemplificativos.', true),
  ('e2000000-0000-4000-b000-000000002119', 'e2000000-0000-4000-a000-00000000034f', 3, 'Ilustra a flexibilidade na estruturação do gênero textual, a qual se concretiza no emprego da linguagem conotativa.', false),
  ('e2000000-0000-4000-b000-00000000211a', 'e2000000-0000-4000-a000-00000000034f', 4, 'Prejudica a sequência do texto, provocando estranheza no leitor ao não desenvolver explicitamente o raciocínio a partir de argumentos.', false),
  ('e2000000-0000-4000-b000-000000002120', 'e2000000-0000-4000-a000-000000000350', 0, 'Narra um fato real vivido por Maria José.', false),
  ('e2000000-0000-4000-b000-000000002121', 'e2000000-0000-4000-a000-000000000350', 1, 'Surpreende o leitor pelo seu efeito poético.', true),
  ('e2000000-0000-4000-b000-000000002122', 'e2000000-0000-4000-a000-000000000350', 2, 'Relata uma experiência teatral profissional.', false),
  ('e2000000-0000-4000-b000-000000002123', 'e2000000-0000-4000-a000-000000000350', 3, 'Descreve uma ação típica de uma mulher sonhadora.', false),
  ('e2000000-0000-4000-b000-000000002124', 'e2000000-0000-4000-a000-000000000350', 4, 'Defende um ponto de vista relativo ao exercício teatral.', false),
  ('e2000000-0000-4000-b000-00000000212a', 'e2000000-0000-4000-a000-000000000351', 0, 'A carta de Pero Vaz de Caminha representa uma das primeiras manifestações artísticas dos portugueses em terras brasileiras e preocupa-se apenas com a estética literária.', false),
  ('e2000000-0000-4000-b000-00000000212b', 'e2000000-0000-4000-a000-000000000351', 1, 'A tela de Portinari retrata indígenas nus com corpos pintados, cuja grande significação é a afirmação da arte acadêmica brasileira e a contestação de uma linguagem moderna.', false),
  ('e2000000-0000-4000-b000-00000000212c', 'e2000000-0000-4000-a000-000000000351', 2, 'A carta, como testemunho histórico-político, mostra o olhar do colonizador sobre a gente da terra, e a pintura destaca, em primeiro plano, a inquietação dos nativos.', true),
  ('e2000000-0000-4000-b000-00000000212d', 'e2000000-0000-4000-a000-000000000351', 3, 'As duas produções, embora usem linguagens diferentes — verbal e não verbal —, cumprem a mesma função social e artística.', false),
  ('e2000000-0000-4000-b000-00000000212e', 'e2000000-0000-4000-a000-000000000351', 4, 'A pintura e a carta de Caminha são manifestações de grupos étnicos diferentes, produzidas em um mesmo momento histórico, retratando a colonização.', false),
  ('e2000000-0000-4000-b000-000000002134', 'e2000000-0000-4000-a000-000000000352', 0, 'Opressão física e moral, que gera rancor nos meninos.', true),
  ('e2000000-0000-4000-b000-000000002135', 'e2000000-0000-4000-a000-000000000352', 1, 'Repressão policial e social, que gera apatia nos meninos.', false),
  ('e2000000-0000-4000-b000-000000002136', 'e2000000-0000-4000-a000-000000000352', 2, 'Polêmica judicial e midiática, que gera confusão entre os meninos.', false),
  ('e2000000-0000-4000-b000-000000002137', 'e2000000-0000-4000-a000-000000000352', 3, 'Concepção educacional e carcerária, que gera comoção nos meninos.', false),
  ('e2000000-0000-4000-b000-000000002138', 'e2000000-0000-4000-a000-000000000352', 4, 'Informação crítica e jornalística, que gera indignação entre os meninos.', false),
  ('e2000000-0000-4000-b000-00000000213e', 'e2000000-0000-4000-a000-000000000353', 0, 'A necessidade de ser socialmente aceito leva o indivíduo a agir de forma dissimulada.', true),
  ('e2000000-0000-4000-b000-00000000213f', 'e2000000-0000-4000-a000-000000000353', 1, 'O sofrimento íntimo torna-se mais ameno quando compartilhado por um grupo social.', false),
  ('e2000000-0000-4000-b000-000000002140', 'e2000000-0000-4000-a000-000000000353', 2, 'A capacidade de perdoar e aceitar as diferenças neutraliza o sentimento de inveja.', false),
  ('e2000000-0000-4000-b000-000000002141', 'e2000000-0000-4000-a000-000000000353', 3, 'O instinto de solidariedade conduz o indivíduo a apiedar-se do próximo.', false),
  ('e2000000-0000-4000-b000-000000002142', 'e2000000-0000-4000-a000-000000000353', 4, 'A transfiguração da angústia em alegria é um artifício nocivo ao convívio social.', false),
  ('e2000000-0000-4000-b000-000000002148', 'e2000000-0000-4000-a000-000000000354', 0, 'A estrela d''alva / No céu desponta / E a lua anda tonta / Com tamanho esplendor. (As pastorinhas, Noel Rosa e João de Barro)', false),
  ('e2000000-0000-4000-b000-000000002149', 'e2000000-0000-4000-a000-000000000354', 1, 'Hoje / Eu quero a rosa mais linda que houver / Quero a primeira estrela que vier / Para enfeitar a noite do meu bem. (A noite do meu bem, Dolores Duran)', false),
  ('e2000000-0000-4000-b000-00000000214a', 'e2000000-0000-4000-a000-000000000354', 2, 'No rancho fundo / Bem pra lá do fim do mundo / Onde a dor e a saudade / Contam coisas da cidade. (No rancho fundo, Ary Barroso e Lamartine Babo)', false),
  ('e2000000-0000-4000-b000-00000000214b', 'e2000000-0000-4000-a000-000000000354', 3, 'Baby Baby / Não adianta chamar / Quando alguém está perdido / Procurando se encontrar. (Ovelha negra, Rita Lee)', true),
  ('e2000000-0000-4000-b000-00000000214c', 'e2000000-0000-4000-a000-000000000354', 4, 'Pois há menos peixinhos a nadar no mar / Do que os beijinhos que eu darei / Na sua boca. (Chega de saudade, Tom Jobim e Vinicius de Moraes)', false),
  ('e2000000-0000-4000-b000-000000002152', 'e2000000-0000-4000-a000-000000000355', 0, '“[...] o Atleta do Século acertou.”', false),
  ('e2000000-0000-4000-b000-000000002153', 'e2000000-0000-4000-a000-000000000355', 1, '“O Rei respondeu sem titubear [...]”.', false),
  ('e2000000-0000-4000-b000-000000002154', 'e2000000-0000-4000-a000-000000000355', 2, '“E provavelmente acertaria novamente hoje.”', false),
  ('e2000000-0000-4000-b000-000000002155', 'e2000000-0000-4000-a000-000000000355', 3, '“Pelé estava se aposentando pra valer pela primeira vez [...]”.', true),
  ('e2000000-0000-4000-b000-000000002156', 'e2000000-0000-4000-a000-000000000355', 4, '“Pela admiração por um de seus colegas de clube daquele ano.”', false),
  ('e2000000-0000-4000-b000-00000000215c', 'e2000000-0000-4000-a000-000000000356', 0, 'Emprego de uma oração adversativa, que orienta a quebra da expectativa ao final.', true),
  ('e2000000-0000-4000-b000-00000000215d', 'e2000000-0000-4000-a000-000000000356', 1, 'Uso de conjunção aditiva, que cria uma relação de causa e efeito entre as ações.', false),
  ('e2000000-0000-4000-b000-00000000215e', 'e2000000-0000-4000-a000-000000000356', 2, 'Retomada do substantivo "mãe", que desfaz a ambiguidade dos sentidos a ele atribuídos.', false),
  ('e2000000-0000-4000-b000-00000000215f', 'e2000000-0000-4000-a000-000000000356', 3, 'Utilização da forma pronominal "la", que reflete um tratamento formal do filho em relação à "mãe".', false),
  ('e2000000-0000-4000-b000-000000002160', 'e2000000-0000-4000-a000-000000000356', 4, 'Repetição da forma verbal "é", que reforça a relação de adição existente entre as orações.', false),
  ('e2000000-0000-4000-b000-000000002166', 'e2000000-0000-4000-a000-000000000357', 0, 'Criticar o transporte rodoviário brasileiro, em razão da grande quantidade de caminhões nas estradas.', false),
  ('e2000000-0000-4000-b000-000000002167', 'e2000000-0000-4000-a000-000000000357', 1, 'Ironizar a dificuldade de locomoção no trânsito urbano, devida ao grande fluxo de veículos.', true),
  ('e2000000-0000-4000-b000-000000002168', 'e2000000-0000-4000-a000-000000000357', 2, 'Expor a questão do movimento como um problema existente desde tempos antigos, conforme frase citada.', false),
  ('e2000000-0000-4000-b000-000000002169', 'e2000000-0000-4000-a000-000000000357', 3, 'Restringir os problemas de tráfego a veículos particulares, defendendo, como solução, o transporte público.', false),
  ('e2000000-0000-4000-b000-00000000216a', 'e2000000-0000-4000-a000-000000000357', 4, 'Propor a ampliação de vias nas estradas, detalhando o espaço exíguo ocupado pelos veículos nas ruas.', false),
  ('e2000000-0000-4000-b000-000000002170', 'e2000000-0000-4000-a000-000000000358', 0, '“[...] a palavra gripe nos chegou após uma série de contágios entre línguas.”', false),
  ('e2000000-0000-4000-b000-000000002171', 'e2000000-0000-4000-a000-000000000358', 1, '“Partiu da Itália em 1743 a epidemia de gripe [...]”.', false),
  ('e2000000-0000-4000-b000-000000002172', 'e2000000-0000-4000-a000-000000000358', 2, '“O primeiro era um termo derivado do latim medieval influentia, que significava ‘influência dos astros sobre os homens’.”', false),
  ('e2000000-0000-4000-b000-000000002173', 'e2000000-0000-4000-a000-000000000358', 3, '“O segundo era apenas a forma nominal do verbo gripper [...]”.', false),
  ('e2000000-0000-4000-b000-000000002174', 'e2000000-0000-4000-a000-000000000358', 4, '“Supõe-se que fizesse referência ao modo violento como o vírus se apossa do organismo infectado.”', true),
  ('e2000000-0000-4000-b000-00000000217a', 'e2000000-0000-4000-a000-000000000359', 0, 'O narrador e Virgília não têm percepção do tempo em seus encontros adúlteros.', false),
  ('e2000000-0000-4000-b000-00000000217b', 'e2000000-0000-4000-a000-000000000359', 1, 'Como “defunto autor”, Brás Cubas reconhece a inutilidade de tentar acompanhar o fluxo do tempo.', false),
  ('e2000000-0000-4000-b000-00000000217c', 'e2000000-0000-4000-a000-000000000359', 2, 'Na contagem das horas, o narrador metaforiza o desejo de triunfar e acumular riquezas.', false),
  ('e2000000-0000-4000-b000-00000000217d', 'e2000000-0000-4000-a000-000000000359', 3, 'O relógio representa a materialização do tempo e redireciona o comportamento idealista de Brás Cubas.', true),
  ('e2000000-0000-4000-b000-00000000217e', 'e2000000-0000-4000-a000-000000000359', 4, 'O narrador compara a duração do sabor do beijo à perpetuidade do relógio.', false),
  ('e2000000-0000-4000-b000-000000002184', 'e2000000-0000-4000-a000-00000000035a', 0, 'Mantém os usuários cada vez menos preocupados com a qualidade da informação.', false),
  ('e2000000-0000-4000-b000-000000002185', 'e2000000-0000-4000-a000-00000000035a', 1, 'Torna o raciocínio de quem navega mais raso, além de fragmentar a atenção de seus usuários.', false),
  ('e2000000-0000-4000-b000-000000002186', 'e2000000-0000-4000-a000-00000000035a', 2, 'Desestimula a inteligência, de acordo com descobertas científicas sobre o cérebro.', false),
  ('e2000000-0000-4000-b000-000000002187', 'e2000000-0000-4000-a000-00000000035a', 3, 'Influencia nossa forma de pensar com a superficialidade dos meios eletrônicos.', false),
  ('e2000000-0000-4000-b000-000000002188', 'e2000000-0000-4000-a000-00000000035a', 4, 'Garante a empresas a obtenção de mais lucro com a recente fragilidade de nossa atenção.', true),
  ('e2000000-0000-4000-b000-00000000218e', 'e2000000-0000-4000-a000-00000000035b', 0, 'Observa os acontecimentos que narra sob uma ótica distante, sendo indiferente aos fatos e às personagens.', false),
  ('e2000000-0000-4000-b000-00000000218f', 'e2000000-0000-4000-a000-00000000035b', 1, 'Relata a história sem ter tido a preocupação de investigar os motivos que levaram aos eventos que a compõem.', false),
  ('e2000000-0000-4000-b000-000000002190', 'e2000000-0000-4000-a000-00000000035b', 2, 'Revela-se um sujeito que reflete sobre questões existenciais e sobre a construção do discurso.', true),
  ('e2000000-0000-4000-b000-000000002191', 'e2000000-0000-4000-a000-00000000035b', 3, 'Admite a dificuldade de escrever uma história em razão da complexidade para escolher as palavras exatas.', false),
  ('e2000000-0000-4000-b000-000000002192', 'e2000000-0000-4000-a000-00000000035b', 4, 'Propõe-se a discutir questões de natureza filosófica e metafísica, incomuns na narrativa de ficção.', false),
  ('e2000000-0000-4000-b000-000000002198', 'e2000000-0000-4000-a000-00000000035c', 0, 'Comprova cientificamente que a vitamina D não é uma vitamina.', false),
  ('e2000000-0000-4000-b000-000000002199', 'e2000000-0000-4000-a000-00000000035c', 1, 'Demonstra a verdadeira importância da vitamina D para a saúde.', false),
  ('e2000000-0000-4000-b000-00000000219a', 'e2000000-0000-4000-a000-00000000035c', 2, 'Enfatiza que a vitamina D é mais comumente produzida pelo corpo que absorvida por meio de alimentos.', true),
  ('e2000000-0000-4000-b000-00000000219b', 'e2000000-0000-4000-a000-00000000035c', 3, 'Afirma que a vitamina D existe na gordura dos peixes e no leite, não em seus derivados.', false),
  ('e2000000-0000-4000-b000-00000000219c', 'e2000000-0000-4000-a000-00000000035c', 4, 'Levanta a possibilidade de o corpo humano produzir artificialmente a vitamina D.', false),
  ('e2000000-0000-4000-b000-0000000021a2', 'e2000000-0000-4000-a000-00000000035d', 0, 'Se desenvolver paralelamente nos meios tradicionais de comunicação e informação.', false),
  ('e2000000-0000-4000-b000-0000000021a3', 'e2000000-0000-4000-a000-00000000035d', 1, 'Cumprir função essencial na contemporaneidade por meio das impressões em papel.', false),
  ('e2000000-0000-4000-b000-0000000021a4', 'e2000000-0000-4000-a000-00000000035d', 2, 'Realizar transição relevante da tradição oral para o progresso das sociedades humanas.', false),
  ('e2000000-0000-4000-b000-0000000021a5', 'e2000000-0000-4000-a000-00000000035d', 3, 'Oferecer melhoria sistemática do padrão de vida e do desenvolvimento social humano.', false),
  ('e2000000-0000-4000-b000-0000000021a6', 'e2000000-0000-4000-a000-00000000035d', 4, 'Fornecer base essencial para o progresso das tecnologias de comunicação e informação.', true),
  ('e2000000-0000-4000-b000-0000000021ac', 'e2000000-0000-4000-a000-00000000035e', 0, 'Resgata conhecidas referências do modernismo mineiro.', false),
  ('e2000000-0000-4000-b000-0000000021ad', 'e2000000-0000-4000-a000-00000000035e', 1, 'Utiliza técnicas e suportes tradicionais na construção das formas.', false),
  ('e2000000-0000-4000-b000-0000000021ae', 'e2000000-0000-4000-a000-00000000035e', 2, 'Articula questões de identidade, território e códigos de linguagens.', true),
  ('e2000000-0000-4000-b000-0000000021af', 'e2000000-0000-4000-a000-00000000035e', 3, 'Imita o papel das celebridades no mundo contemporâneo.', false),
  ('e2000000-0000-4000-b000-0000000021b0', 'e2000000-0000-4000-a000-00000000035e', 4, 'Camufla o aspecto plástico e a composição visual de sua montagem.', false),
  ('e2000000-0000-4000-b000-0000000021b6', 'e2000000-0000-4000-a000-00000000035f', 0, 'Tentar persuadir o leitor acerca da necessidade de se tomarem certas medidas para a elaboração de um livro.', false),
  ('e2000000-0000-4000-b000-0000000021b7', 'e2000000-0000-4000-a000-00000000035f', 1, 'Enfatizar a percepção subjetiva do autor, que projeta para sua obra seus sonhos e histórias.', false),
  ('e2000000-0000-4000-b000-0000000021b8', 'e2000000-0000-4000-a000-00000000035f', 2, 'Apontar para o estabelecimento de interlocução de modo superficial e automático, entre o leitor e o livro.', false),
  ('e2000000-0000-4000-b000-0000000021b9', 'e2000000-0000-4000-a000-00000000035f', 3, 'Fazer um exercício de reflexão a respeito dos princípios que estruturam a forma e o conteúdo de um livro.', true),
  ('e2000000-0000-4000-b000-0000000021ba', 'e2000000-0000-4000-a000-00000000035f', 4, 'Retratar as etapas do processo de produção de um livro, as quais antecedem o contato entre leitor e obra.', false),
  ('e2000000-0000-4000-b000-0000000021c0', 'e2000000-0000-4000-a000-000000000360', 0, 'Direcionamentos possíveis para uma leitura crítica de dados histórico-culturais.', true),
  ('e2000000-0000-4000-b000-0000000021c1', 'e2000000-0000-4000-a000-000000000360', 1, 'Forma clássica da construção poética brasileira.', false),
  ('e2000000-0000-4000-b000-0000000021c2', 'e2000000-0000-4000-a000-000000000360', 2, 'Rejeição à ideia do Brasil como o país do futebol.', false),
  ('e2000000-0000-4000-b000-0000000021c3', 'e2000000-0000-4000-a000-000000000360', 3, 'Intervenções de um leitor estrangeiro no exercício de leitura poética.', false),
  ('e2000000-0000-4000-b000-0000000021c4', 'e2000000-0000-4000-a000-000000000360', 4, 'Lembretes de palavras tipicamente brasileiras substitutivas das originais.', false),
  ('e2000000-0000-4000-b000-0000000021ca', 'e2000000-0000-4000-a000-000000000361', 0, 'Expor as características comuns entre os povos indígenas no Brasil e suas ideias modernas e civilizadas.', false),
  ('e2000000-0000-4000-b000-0000000021cb', 'e2000000-0000-4000-a000-000000000361', 1, 'Trazer uma abordagem inédita sobre os povos indígenas no Brasil e, assim, ser reconhecido como especialista no assunto.', false),
  ('e2000000-0000-4000-b000-0000000021cc', 'e2000000-0000-4000-a000-000000000361', 2, 'Mostrar os povos indígenas vivendo em comunhão com a natureza, e, por isso, sugerir que se deve respeitar o meio ambiente e esses povos.', false),
  ('e2000000-0000-4000-b000-0000000021cd', 'e2000000-0000-4000-a000-000000000361', 3, 'Usar a conhecida oposição entre moderno e antigo como uma forma de respeitar a maneira ultrapassada como vivem os povos indígenas em diferentes regiões do Brasil.', false),
  ('e2000000-0000-4000-b000-0000000021ce', 'e2000000-0000-4000-a000-000000000361', 4, 'Apresentar informações pouco divulgadas a respeito dos indígenas no Brasil, para defender o caráter desses povos como civilizações, em contraposição a visões preconcebidas.', true),
  ('e2000000-0000-4000-b000-0000000021d4', 'e2000000-0000-4000-a000-000000000362', 0, 'Crítica, expressa pelas ironias.', true),
  ('e2000000-0000-4000-b000-0000000021d5', 'e2000000-0000-4000-a000-000000000362', 1, 'Resignada, expressa pelas enumerações.', false),
  ('e2000000-0000-4000-b000-0000000021d6', 'e2000000-0000-4000-a000-000000000362', 2, 'Indignada, expressa pelos discursos diretos.', false),
  ('e2000000-0000-4000-b000-0000000021d7', 'e2000000-0000-4000-a000-000000000362', 3, 'Agressiva, expressa pela contra-argumentação.', false),
  ('e2000000-0000-4000-b000-0000000021d8', 'e2000000-0000-4000-a000-000000000362', 4, 'Alienada, expressa pela negação da realidade.', false),
  ('e2000000-0000-4000-b000-0000000021de', 'e2000000-0000-4000-a000-000000000363', 0, 'Reconhece a espécie do animal avistado.', false),
  ('e2000000-0000-4000-b000-0000000021df', 'e2000000-0000-4000-a000-000000000363', 1, 'Tem dúvida sobre a pronúncia do nome do réptil.', false),
  ('e2000000-0000-4000-b000-0000000021e0', 'e2000000-0000-4000-a000-000000000363', 2, 'Desconsidera o conteúdo linguístico da pergunta.', true),
  ('e2000000-0000-4000-b000-0000000021e1', 'e2000000-0000-4000-a000-000000000363', 3, 'Constata o fato de um bicho cruzar a frente do carro.', false),
  ('e2000000-0000-4000-b000-0000000021e2', 'e2000000-0000-4000-a000-000000000363', 4, 'Apresenta duas possibilidades de sentido para a mesma palavra.', false),
  ('e2000000-0000-4000-b000-0000000021e8', 'e2000000-0000-4000-a000-000000000364', 0, 'Representa a amplitude de informações que compõem a internet, às quais temos acesso em redes sociais e sites de busca.', false),
  ('e2000000-0000-4000-b000-0000000021e9', 'e2000000-0000-4000-a000-000000000364', 1, 'Faz uma denúncia quanto às informações que são omitidas dos usuários da rede, sendo empregada no sentido conotativo.', true),
  ('e2000000-0000-4000-b000-0000000021ea', 'e2000000-0000-4000-a000-000000000364', 2, 'Diz respeito a um buraco negro digital, onde estão escondidas as informações buscadas pelo usuário nos sites que acessa.', false),
  ('e2000000-0000-4000-b000-0000000021eb', 'e2000000-0000-4000-a000-000000000364', 3, 'Está associada a um conjunto de restrições sociais presentes na vida daqueles que estão sempre conectados à internet.', false),
  ('e2000000-0000-4000-b000-0000000021ec', 'e2000000-0000-4000-a000-000000000364', 4, 'Remete às bases de dados da web, protegidas por senhas ou assinaturas e às quais o navegador não tem acesso.', false),
  ('e2000000-0000-4000-b000-0000000021f2', 'e2000000-0000-4000-a000-000000000365', 0, 'Atingir um grupo maior de espectadores.', false),
  ('e2000000-0000-4000-b000-0000000021f3', 'e2000000-0000-4000-a000-000000000365', 1, 'Dificultar a identificação do agressor incógnito.', true),
  ('e2000000-0000-4000-b000-0000000021f4', 'e2000000-0000-4000-a000-000000000365', 2, 'Impedir a retomada de valores consolidados pela vítima.', false),
  ('e2000000-0000-4000-b000-0000000021f5', 'e2000000-0000-4000-a000-000000000365', 3, 'Possibilitar a participação de um número maior de autores.', false),
  ('e2000000-0000-4000-b000-0000000021f6', 'e2000000-0000-4000-a000-000000000365', 4, 'Proporcionar o uso de uma variedade de ferramentas da internet.', false),
  ('e2000000-0000-4000-b000-0000000021fc', 'e2000000-0000-4000-a000-000000000366', 0, 'Exemplifica o aumento da expectativa de vida da população.', false),
  ('e2000000-0000-4000-b000-0000000021fd', 'e2000000-0000-4000-a000-000000000366', 1, 'Explica o crescimento da confiança na instituição do casamento.', false),
  ('e2000000-0000-4000-b000-0000000021fe', 'e2000000-0000-4000-a000-000000000366', 2, 'Mostra que a população brasileira aumentou nos últimos cinco anos.', false),
  ('e2000000-0000-4000-b000-0000000021ff', 'e2000000-0000-4000-a000-000000000366', 3, 'Indica que as taxas de casamento e emprego cresceram na mesma proporção.', false),
  ('e2000000-0000-4000-b000-000000002200', 'e2000000-0000-4000-a000-000000000366', 4, 'Sintetiza o crescente número de casamentos e de ocupação no mercado de trabalho.', true),
