  ('e2000000-0000-4000-a000-00000000029b', 'ENEM-2012-116', 11, 442, 'enem', 3, 2, 2012, 'multiple_choice', 'Escolas e textos literários', '**LXXVIII** (Camões, 1525?-1580)

